INTRO = 'Sober and mortified the next morning, Seung-chan eats pancakes at the dining table while Ye-jin and Joon-mo scramble to explain why two unmarried friends live under one roof. Listen for "donggeo", cohabitation, which Ye-jin rebrands as a temporary address-sharing relationship.'
STORY = [('yejin', '너 호떡 사면서 또 마분지 안 챙겼더라.', 'When you bought the pancakes, you forgot the cardboard cup again.', [(82, '너 호떡 사면서 또 마분지 안 챙겼더라')], ''), ('seungchan', '죄송합니다. 다음번에 꼭 챙기겠습니다.', 'I am sorry. I will definitely make sure to get it next time.', [(84, '죄송합니다. 다음번에 꼭 챙기겠습니다')], ''), ('yejin', '왜 이렇게 예의가 바르지? 어제처럼 해.', 'Why are you being so polite? Act like you did yesterday.', [(85, '왜 이렇게 예의가 바르지'), (86, '어제처럼 해')], ''), ('joonmo', '여기 어떻게 온 거야? 우리 집 어떻게 알았어?', 'How did you get here? How did you know our apartment?', [(97, '여기 어떻게 온 거야'), (98, '우리 집 어떻게 알았어')], ''), ('seungchan', '제가 여기 바로 앞동 삽니다.', 'I live in the building right in front of this one.', [(99, '제가 여기'), (100, '앞동 삽니다')], ''), ('seungchan', '우연히 두 분이 한 집에 들어가시는 걸 봐서요.', 'By chance, I saw the two of you going into the same home.', [(104, '우연히 두 분이 한 집에 들어가시는 걸 봐서')], ''), ('joonmo', '오해할 수 있는 상황인 거 내가 충분히 알아.', 'I fully understand that this is a situation you could misunderstand.', [(112, '오해할 수 있는 상황인 거 내가 충분히 알아')], ''), ('yejin', '그런 거 아니야. 그냥 같이 사는 거야.', 'It is nothing like that. We just live together.', [(115, '그런 거 아니야'), (117, '그냥 같이 사는 거야')], ''), ('yejin', '이건 동거가 아니고 일시적인 주소 공유 관계야.', 'This is not cohabitation, it is a temporary address-sharing relationship.', [(139, '이건 동거가 아니고 일시적인 주소 공유 관계')], ''), ('joonmo', '나랑 예진이는 초등학교 때부터 그냥 친구야.', 'Ye-jin and I have simply been friends since elementary school.', [(154, '나랑 예진이는 초등학교 때부터 친구')], ''), ('seungchan', '네, 일시적으로 주소를 공유하고 계시는 거군요.', 'Right, so you are temporarily sharing an address.', [(158, '일시적으로 주소를 공유하고 계시다')], ''), ('yejin', '나 진짜 들킨 연예인 된 기분이야.', 'I really feel like a celebrity who just got caught.', [(160, '연예인 된 기분이야')], '')]
OPENER = "Now let's go through it line by line with the English translation."
WALK = [(0, None, "'When you bought the pancakes, you forgot the cardboard cup again.'"), (1, None, "'I am sorry. I will definitely make sure to get it next time.'"), (2, None, "'Why are you being so polite? Act like you did yesterday.'"), (3, None, "'How did you get here? How did you know our apartment?'"), (4, None, "'I live in the building right in front of this one.'"), (5, None, "'By chance, I saw the two of you going into the same home.'"), (6, None, "'I fully understand that this is a situation you could misunderstand.'"), (7, None, "'It is nothing like that. We just live together.'"), (8, None, "'This is not cohabitation, it is a temporary address-sharing relationship.'"), (9, None, "'Ye-jin and I have simply been friends since elementary school.'"), (10, None, "'Right, so you are temporarily sharing an address.'"), (11, None, "'I really feel like a celebrity who just got caught.'")]
